1	import { readFileSync } from "node:fs";
2	import { join } from "node:path";
3	import { describe, expect, it } from "vitest";
4	import { DISTRICTS } from "../../script/data/sceneGrammar";
5	import type { VocabProperty } from "../types";
6	import {
7		assignRoom,
8		isKnownWordClass,
9		KNOWN_WORD_CLASSES,
10		NOUN_SUBDISTRICTS,
11		ROOMS,
12		ROOMS_AND_DISTRICTS_ARE_DISJOINT,
13		reportNounSubdistrictOverflows,
14		roomExposureFor,
15		roomForWordClass,
16	} from "./rooms";
17	
18	const VOCAB_PATH = join(import.meta.dirname, "vocabulary.json");
19	
20	interface RawVocabEntry {
21		word_class: string;
22	}
23	
24	function loadCorpusWordClasses(): Set<string> {
25		const raw = JSON.parse(readFileSync(VOCAB_PATH, "utf8")) as RawVocabEntry[];
26		return new Set(raw.map((entry) => entry.word_class).filter((c) => c !== ""));
27	}
28	
29	const ALL_VOCAB_PROPERTIES: VocabProperty[] = [
30		"thaiToEnglish",
31		"englishToThai",
32		"audioRecognition",
33		"toneIdentification",
34		"spelling",
35		"spellingFromAudio",
36	];
37	
38	// AC1 -----------------------------------------------------------------------
39	
40	describe("AC1: every corpus word class maps to exactly one room", () => {
41		it("maps every non-empty word_class value found in the corpus to a room", () => {
42			const corpusClasses = loadCorpusWordClasses();
43			expect(corpusClasses.size).toBeGreaterThan(0);
44			for (const wordClass of corpusClasses) {
45				expect(
46					isKnownWordClass(wordClass),
47					`corpus word_class "${wordClass}" is not in KNOWN_WORD_CLASSES`,
48				).toBe(true);
49			}
50		});
51	
52		it("declares no more and no fewer word classes than the corpus carries", () => {
53			const corpusClasses = loadCorpusWordClasses();
54			expect(new Set(KNOWN_WORD_CLASSES)).toEqual(corpusClasses);
55		});
56	
57		it("maps every known word class to exactly one room, total in both directions", () => {
58			for (const wordClass of KNOWN_WORD_CLASSES) {
59				const room = roomForWordClass(wordClass);
60				expect(ROOMS).toContain(room);
61			}
62		});
63	
64		it("every room has at least one word class mapping to it", () => {
65			const reached = new Set(KNOWN_WORD_CLASSES.map(roomForWordClass));
66			for (const room of ROOMS) {
67				expect(reached.has(room), `no word class maps to room "${room}"`).toBe(
68					true,
69				);
70			}
71		});
72	
73		it("maps verbs and adjectives to the same room", () => {
74			expect(roomForWordClass("v")).toBe(roomForWordClass("adj"));
75		});
76	
77		it("gives classifiers and particles their own rooms, not folded into connectors", () => {
78			const connectorsRoom = roomForWordClass("conj");
79			expect(roomForWordClass("clf")).not.toBe(connectorsRoom);
80			expect(roomForWordClass("part")).not.toBe(connectorsRoom);
81			expect(roomForWordClass("clf")).not.toBe(roomForWordClass("part"));
82		});
83	});
84	
85	// AC2 -------------------------------------------------------------------
86	
87	describe("AC2: rooms and scene-grammar districts are disjoint vocabularies", () => {
88		it("shares no name between ROOMS and DISTRICTS", () => {
89			expect(ROOMS_AND_DISTRICTS_ARE_DISJOINT).toBe(true);
90			const roomSet = new Set<string>(ROOMS);
91			for (const district of DISTRICTS) {
92				expect(roomSet.has(district)).toBe(false);
93			}
94		});
95	});
96	
97	// AC3 -------------------------------------------------------------------
98	
99	describe("AC3: noun sub-districts declare a bounded capacity each", () => {
100		it("declares at least one sub-district, each with a positive capacity", () => {
101			expect(NOUN_SUBDISTRICTS.length).toBeGreaterThan(0);
102			for (const subdistrict of NOUN_SUBDISTRICTS) {
103				expect(subdistrict.capacity).toBeGreaterThan(0);
104			}
105		});
106	
107		it("reports a sub-district pushed past its declared capacity", () => {
108			const first = NOUN_SUBDISTRICTS[0];
109			const overflows = reportNounSubdistrictOverflows({
110				[first.name]: first.capacity + 1,
111			});
112			expect(overflows).toEqual([
113				{
114					subdistrict: first.name,
115					capacity: first.capacity,
116					count: first.capacity + 1,
117				},
118			]);
119		});
120	
121		it("does not report a sub-district at or under its declared capacity", () => {
122			const first = NOUN_SUBDISTRICTS[0];
123			const overflows = reportNounSubdistrictOverflows({
124				[first.name]: first.capacity,
125			});
126			expect(overflows).toEqual([]);
127		});
128	});
129	
130	// AC4 -------------------------------------------------------------------
131	
132	describe("AC4: the room is never exposed before the learner has acted", () => {
133		it.each(
134			ALL_VOCAB_PROPERTIES,
135		)("for %s: hidden before acting, obtainable on request, present after reveal", (property) => {
136			const before = roomExposureFor(property, {
137				revealed: false,
138				hintRequested: false,
139			});
140			expect(before.visible).toBe(false);
141	
142			const onRequest = roomExposureFor(property, {
143				revealed: false,
144				hintRequested: true,
145			});
146			expect(onRequest.visible).toBe(true);
147			if (onRequest.visible) {
148				expect(onRequest.via).toBe("hint");
149			}
150	
151			const afterReveal = roomExposureFor(property, {
152				revealed: true,
153				hintRequested: false,
154			});
155			expect(afterReveal.visible).toBe(true);
156			if (afterReveal.visible) {
157				expect(afterReveal.via).toBe("reveal");
158			}
159		});
160	
161		it("records a room requested as a hint distinctly from unaided recall", () => {
162			const askedThenRevealed = roomExposureFor("thaiToEnglish", {
163				revealed: true,
164				hintRequested: true,
165			});
166			const recalledUnaided = roomExposureFor("thaiToEnglish", {
167				revealed: true,
168				hintRequested: false,
169			});
170			expect(askedThenRevealed.hintUsed).toBe(true);
171			expect(recalledUnaided.hintUsed).toBe(false);
172		});
173	});
174	
175	// AC5 -------------------------------------------------------------------
176	
177	describe("AC5: a word is in exactly one of three room-assignment states", () => {
178		it("assigns a known word class to its room", () => {
179			const result = assignRoom("n");
180			expect(result).toEqual({ state: "assigned", room: "things" });
181		});
182	
183		it("reports an unrecognised, non-empty word class as unassignable with a reason", () => {
184			const result = assignRoom("xyz");
185			expect(result.state).toBe("unassignable");
186			if (result.state === "unassignable") {
187				expect(result.reason.length).toBeGreaterThan(0);
188			}
189		});
190	
191		it("reports an empty word class as unclassified, never as unassignable", () => {
192			const result = assignRoom("");
193			expect(result).toEqual({ state: "unclassified" });
194		});
195	
196		it("produces three distinct state values", () => {
197			const states = new Set(
198				[assignRoom("n"), assignRoom("xyz"), assignRoom("")].map((r) => r.state),
199			);
200			expect(states).toEqual(
201				new Set(["assigned", "unassignable", "unclassified"]),
202			);
203		});
204	});
205

