255		const perClassCorrect = new Map<string, number>();
256	
257		for (const entry of entries) {
258			const truth = entry.word_class;
259			truths.set(truth, (truths.get(truth) ?? 0) + 1);
260			const predicted = entry.word_class_predicted;
261			if (predicted === null || predicted === undefined) {
262				residue += 1;
263			} else if (predicted === truth) {
264				correct += 1;
265				perClassCorrect.set(truth, (perClassCorrect.get(truth) ?? 0) + 1);
266			}
267		}
268	
269		const total = entries.length;
270		const [majorityClass = "", majorityCorrect = 0] =
271			[...truths].sort((a, b) =>
272				b[1] === a[1] ? a[0].localeCompare(b[0]) : b[1] - a[1],
273			)[0] ?? [];
274		let balanced = 0;
275		for (const [cls, n] of truths) {
276			balanced += (perClassCorrect.get(cls) ?? 0) / n;
277		}
