318			expect(wordClassStateFor(backfilledEntry)).toEqual({
319				state: "backfilled",
320				wordClass: "v",
321				rule: "fitted-gloss-lexicon",
322			});
323			expect(wordClassProvenanceOf(backfilledEntry)).toBe("backfill");
324		});
325	
326		it("reads a refused class as unclassifiable with a reason, never as unclassified", () => {
327			const state = wordClassStateFor(unclassifiableEntry);
328			expect(state.state).toBe("unclassifiable");
329			expect(state.state).not.toBe("unrecorded");
330			if (state.state === "unclassifiable") {
331				expect(state.reason).toMatch(/\S/);
332			}
333			// The distinction the criterion turns on: an entry nothing has run over
334			// is a different state, and the two do not collapse into each other.
335			expect(wordClassStateFor({ thai: "x", word_class: "" })).toEqual({
336				state: "unrecorded",
337			});
338		});
339	
340		it("keeps the three states three distinct values", () => {
341			const states = [sourceEntry, backfilledEntry, unclassifiableEntry].map(
342				(entry) => wordClassStateFor(entry).state,
343			);
344			expect(new Set(states).size).toBe(3);
345			expect(states).not.toContain("unrecorded");
346		});
347	
348		it("refuses to read a backfill that left neither a class nor a reason as any of the three", () => {
349			// A backfill that ran, decided nothing and said nothing is a failure. It
350			// must not render identically to a legitimate outcome.
351			expect(
352				wordClassStateFor({
353					thai: "x",
354					word_class: "",
355					word_class_provenance: "backfill",
356				}),
357			).toEqual({ state: "unrecorded" });
358		});
359	});
360	
361	// Idempotency ---------------------------------------------------------------
362	
363	describe("re-running the backfill changes nothing", () => {
364		it("leaves no entry in a shape a second run would read differently", () => {
365			// The script's idempotency rests on two properties of what it wrote, and
366			// both are checkable here. First, `_source_class` treats a
367			// provenance="backfill" value as *not* a source value, so a second run
368			// refits on source labels only and cannot feed on its own guesses.
369			// Second, the classifier is deterministic, so the same inputs give the
370			// same output. What would break the first is an entry whose provenance
371			// and fields disagree about which it is.
372			for (const entry of CORPUS) {
373				const state = wordClassStateFor(entry);
374				if (state.state === "from-source") {
375					expect(entry.word_class_unclassifiable, describeEntry(entry)).toBe(
376						undefined,
377					);
378					expect(entry.word_class_rule, describeEntry(entry)).toBe(undefined);
379				}
380				if (state.state === "backfilled") {
381					expect(entry.word_class_predicted, describeEntry(entry)).toBe(
382						undefined,
383					);
384					expect(entry.word_class_unclassifiable, describeEntry(entry)).toBe(
385						undefined,
386					);
387				}
388				if (state.state === "unclassifiable") {
389					expect(entry.word_class_rule, describeEntry(entry)).toBe(undefined);
390					expect(entry.word_class, describeEntry(entry)).toBe("");
391				}
392			}
393		});
394	
395		it("flags exactly the held-out entries and no others", () => {
396			for (const entry of CORPUS) {
397				const flagged = entry.word_class_heldout === true;
398				const shouldBeFlagged =
399					wordClassStateFor(entry).state === "from-source" &&
400					isHeldOut(entry.thai);
401				expect(flagged, describeEntry(entry)).toBe(shouldBeFlagged);
402			}
403		});
404	});
