130	 * uses, as human-readable reasons. Empty means consistent.
131	 *
132	 * Two ways prose can go wrong, and both are checked:
133	 * - it reaches for an off-register form of a character's pronoun (ดิฉัน where
134	 *   Chan is declared informal);
135	 * - it puts a character's pronoun in a scene that never declared that
136	 *   character, so nothing holds the register at all.
137	 */
138	export function registerViolations(
139		text: string,
140		used: readonly CharacterId[],
141	): string[] {
