148					);
149				}
150			}
151			if (text.includes(character.pronoun) && !used.includes(character.id)) {
152				violations.push(
153					`stages ${character.pronoun} without declaring ${character.name}, so no register governs it`,
154				);
155			}
156		}
157		return violations;
158	}
