import type { Room } from "../types";

// ============================================================================
// Pom and Chan — the recurring cast every vocabulary mnemonic draws on
// ============================================================================
// Two characters, named for the gendered first-person pronouns ผม and ฉัน.
// They teach that split by exposure rather than by a rule: a learner who meets
// them in scene after scene picks up which pronoun goes with which speaker
// without ever being told.
//
// They also give the mnemonics a fixed cast, so images compose instead of
// competing — the same two people in a hundred scenes are two people, while a
// hundred unnamed actors are a hundred things to hold.
//
// **They are not natives of a class district.** ผ and ฉ are both high class, so
// a character pinned to the high district (temple, see sceneGrammar.ts) would
// be unusable in the other two, and wherever they did appear the class signal
// would fight the room signal for the same image. The cast moves between rooms
// instead; `homeRoom` is null by construction and `characters.test.ts` holds
// them to appearing in more than one.

/**
 * The politeness registers a character may be fixed to.
 *
 * Thai first person is not one word but a register ladder, and a mnemonic that
 * reaches for whichever rung fits the sentence teaches the ladder by accident.
 * Each character sits on exactly one rung, declared here.
 */
export const REGISTERS = ["informal", "polite", "formal"] as const;

export type Register = (typeof REGISTERS)[number];

export const CHARACTER_IDS = ["pom", "chan"] as const;

export type CharacterId = (typeof CHARACTER_IDS)[number];

/** A pronoun form this character does NOT use, and the register it belongs to. */
export interface RegisterVariant {
	form: string;
	register: Register;
	note: string;
}

export interface Character {
	id: CharacterId;
	/** The name as it appears in mnemonic prose. */
	name: string;
	/** The Thai first-person pronoun the character is named for and speaks with. */
	pronoun: string;
	pronounRomanized: string;
	/** The rung on the register ladder this character is fixed to. */
	register: Register;
	/**
	 * Null by construction: the cast is not native to a class district. See the
	 * module comment — a character fixed to one district is unusable in the
	 * other two.
	 */
	homeRoom: Room | null;
	/**
	 * Pronoun forms of the same person in another register. A mnemonic using
	 * this character may not reach for one of these; that is what
	 * {@link registerViolations} checks.
	 */
	registerVariants: readonly RegisterVariant[];
}

export const CHARACTERS: readonly Character[] = [
	{
		id: "pom",
		name: "Pom",
		pronoun: "ผม",
		pronounRomanized: "phǒm",
		// ผม is the everyday polite male first person: neutral enough for a
		// stranger, unmarked enough not to sound stiff with a friend. Pom is
		// fixed there so no scene has to decide.
		register: "polite",
		homeRoom: null,
		registerVariants: [
			{
				form: "กู",
				register: "informal",
				note: "blunt and intimate; rude outside close friends",
			},
			{
				form: "ข้าพเจ้า",
				register: "formal",
				note: "written and ceremonial; wrong in any spoken scene",
			},
		],
	},
	{
		id: "chan",
		name: "Chan",
		pronoun: "ฉัน",
		pronounRomanized: "chǎn",
		// ฉัน is informal — friends, family, songs. ดิฉัน is its formal
		// counterpart, and the pair is exactly why this field exists: a learner
		// meeting Chan constantly adopts whichever of the two the scenes happen
		// to use, so the scenes do not get to happen to use either.
		register: "informal",
		homeRoom: null,
		registerVariants: [
			{
				form: "ดิฉัน",
				register: "formal",
				note: "the formal counterpart of ฉัน; used by women in business and public speech",
			},
			{
				form: "หนู",
				register: "informal",
				note: "a younger speaker to an older listener; carries an age relation ฉัน does not",
			},
		],
	},
];

const CHARACTERS_BY_ID = new Map(CHARACTERS.map((c) => [c.id, c]));

/** The character with this id. Throws rather than returning undefined: the id set is closed. */
export function characterFor(id: CharacterId): Character {
	const character = CHARACTERS_BY_ID.get(id);
	if (!character) {
		throw new Error(`unknown character id: ${id}`);
	}
	return character;
}

/**
 * Every way `text` is inconsistent with the declared register of the cast it
 * uses, as human-readable reasons. Empty means consistent.
 *
 * Two ways prose can go wrong, and both are checked:
 * - it reaches for an off-register form of a character's pronoun (ดิฉัน where
 *   Chan is declared informal);
 * - it puts a character's pronoun in a scene that never declared that
 *   character, so nothing holds the register at all.
 */
export function registerViolations(
	text: string,
	used: readonly CharacterId[],
): string[] {
	const violations: string[] = [];
	for (const character of CHARACTERS) {
		for (const variant of character.registerVariants) {
			if (text.includes(variant.form)) {
				violations.push(
					`uses ${variant.form} (${variant.register}) where ${character.name} is declared ${character.register}`,
				);
			}
		}
		if (text.includes(character.pronoun) && !used.includes(character.id)) {
			violations.push(
				`stages ${character.pronoun} without declaring ${character.name}, so no register governs it`,
			);
		}
	}
	return violations;
}

import type { Validation } from "../../script/data/sceneGrammar";
import {
	CHARACTER_IDS,
	type CharacterId,
	characterFor,
	registerViolations,
} from "../data/characters";
import { assignRoom } from "../data/rooms";
import vocabulary from "../data/vocabulary.json";
import type { Room, VocabEntry, VocabProperty } from "../types";
import { ROOMS } from "../types";

// ============================================================================
// Vocabulary mnemonics — staged in rooms, cast with Pom and Chan
// ============================================================================
// A symbol's mnemonic binds shape to sound (sceneGrammar.ts). A word has no
// shape to bind, so a word's mnemonic binds a *scene* to its sound, and stages
// that scene in the room its part of speech lives in (rooms.ts).
//
// The room is never a pre-reveal cue — see `roomExposureFor` in rooms.ts and
// the phase README's rejection of literal memory palaces. Staging is for
// consistency and for post-reveal confirmation: the same six places and the
// same two people across every word, so a new image joins the others instead
// of competing with them.

// ----------------------------------------------------------------------------
// Room anchors — the one word that puts a scene in its room
// ----------------------------------------------------------------------------
// Declaring `room` on a record makes the room checkable against the corpus;
// it does not make the *prose* checkable, and a scene declared "connectors"
// while describing a shelf is exactly the failure AC2 names. So each room owns
// one anchor word, the scene has to contain its own and no other's, and the
// contradiction becomes a thing a test can see.
//
// The anchors are deliberately disjoint from the class districts (temple,
// market, harbor): a learner holds rooms and districts as two vocabularies,
// never one word meaning both.

export const ROOM_ANCHORS: Readonly<Record<Room, string>> = {
	"people-and-pronouns": "hallway",
	things: "shelf",
	"actions-and-states": "workshop",
	connectors: "corridor",
	particles: "doorway",
	"counting-and-classifiers": "abacus",
};

const ANCHOR_ENTRIES: readonly (readonly [Room, string])[] = ROOMS.map(
	(room) => [room, ROOM_ANCHORS[room]] as const,
);

// ----------------------------------------------------------------------------
// The record
// ----------------------------------------------------------------------------

export interface VocabMnemonic {
	/** The corpus `thai` this stages. */
	thai: string;
	/** The corpus `rank` it was drawn from — the only thing that tells two homographic entries apart. */
	rank: number;
	/** The room the scene is staged in. Must equal the room the word's class assigns. */
	room: Room;
	/** The recurring cast in this scene, by id. Empty is allowed; a name in the prose without the id is not. */
	characters: readonly CharacterId[];
	/** The image. Contains its room's anchor and no other room's. */
	sceneCue: string;
	/** What in the scene carries the Thai sound. A record without one describes a meaning and teaches no word. */
	soundCue: string;
	/** What the scene resolves to. */
	meaningCue: string;
}

/** The one prose rendering of a record: scene, then sound, then meaning. */
export function composeVocabMnemonic(record: VocabMnemonic): string {
	return `${record.sceneCue} ${record.soundCue} — ${record.meaningCue}`;
}

function isBlank(value: string | null | undefined): boolean {
	return value === null || value === undefined || value.trim() === "";
}

/** The loosely-typed shape validation accepts, so deficient records can be checked. */
export interface VocabMnemonicInput {
	room?: Room | string | null;
	characters?: readonly string[];
	sceneCue?: string | null;
	soundCue?: string | null;
	meaningCue?: string | null;
}

const ROOM_SET: ReadonlySet<string> = new Set(ROOMS);

/**
 * A record validates only if it declares a real room, stages its scene there
 * in prose, names every character it declares, binds a sound, and says what
 * the scene resolves to. Failures name their fields — a refused record must
 * never look like an empty one.
 */
export function validateVocabMnemonic(record: VocabMnemonicInput): Validation {
	const missing: string[] = [];
	const invalid: string[] = [];

	if (isBlank(record.sceneCue)) missing.push("sceneCue");
	if (isBlank(record.soundCue)) missing.push("soundCue");
	if (isBlank(record.meaningCue)) missing.push("meaningCue");
	if (isBlank(typeof record.room === "string" ? record.room : null)) {
		missing.push("room");
	} else if (!ROOM_SET.has(record.room as string)) {
		invalid.push(`room: "${record.room}" is not one of the six rooms`);
	}

	const scene = record.sceneCue ?? "";
	if (typeof record.room === "string" && ROOM_SET.has(record.room)) {
		for (const [room, anchor] of ANCHOR_ENTRIES) {
			const staged = scene.toLowerCase().includes(anchor);
			if (room === record.room && !staged) {
				missing.push(`sceneCue: stages nothing in the ${anchor}`);
			}
			if (room !== record.room && staged) {
				invalid.push(
					`sceneCue: staged in the ${anchor} (${room}) but declared ${record.room}`,
				);
			}
		}
	}

	for (const id of record.characters ?? []) {
		if (!CHARACTER_IDS.includes(id as CharacterId)) {
			invalid.push(`characters: "${id}" is not one of the recurring cast`);
			continue;
		}
		if (!scene.includes(characterFor(id as CharacterId).name)) {
			invalid.push(
				`characters: declares ${id} but the scene never stages them`,
			);
		}
	}

	for (const violation of registerViolations(
		`${record.sceneCue ?? ""} ${record.soundCue ?? ""} ${record.meaningCue ?? ""}`,
		(record.characters ?? []).filter((id): id is CharacterId =>
			CHARACTER_IDS.includes(id as CharacterId),
		),
	)) {
		invalid.push(`register: ${violation}`);
	}

	return missing.length === 0 && invalid.length === 0
		? { ok: true }
		: { ok: false, missing, invalid };
}

