	});
});

// ---------------------------------------------------------------------------
// AC3 — every mnemonic validates against the scene-grammar schema
// ---------------------------------------------------------------------------

describe("scene-grammar conformance", () => {
	it("validates every staged mnemonic", () => {
		const failures: string[] = [];
		for (const record of VOCAB_MNEMONICS) {
